SELECT DATE_FORMAT(sign_time, '%Y-%m-%d') AS sign_date, COUNT(*) AS count FROM business_teacher_sign_records
and DATE_FORMAT(sign_time, '%Y-%m-01') = #{signTime}
GROUP BY sign_date ORDER BY sign_date

SELECT DATE_FORMAT(t.sign_time, '%Y-%m-%d') AS sign_date, COUNT(*) AS count FROM business_student_sign_records s Left join business_teacher_sign_records t on s.teacher_sign_id = t.id
and DATE_FORMAT(t.sign_time, '%Y-%m-01') = #{signTime}
GROUP BY sign_date ORDER BY sign_date
